const fs=require('fs'),path=require('path'),http=require('http'),cp=require('child_process'),{chromium}=require('playwright');
const root=process.cwd(),out='qa-site-links-preview-20261119',changed=['index.html','house-cleaning/index.html','cursor-test/index.html'];
fs.mkdirSync(out,{recursive:true});const old={},latest={},must=(v,e)=>{if(!v)throw Error(e)};
for(const f of changed){old[f]=cp.execFileSync('git',['show','origin/main:'+f],{encoding:'utf8'});latest[f]=fs.readFileSync(f,'utf8');}
const hrefs=z=>[...z.matchAll(/\bhref=(["'])(.*?)\1/g)].map(m=>m[2]);
const scripts=z=>[...z.matchAll(/<script\b[^>]*>[\s\S]*?<\/script>/gi)].map(x=>x[0]);
for(const f of changed){must(JSON.stringify(scripts(old[f]))===JSON.stringify(scripts(latest[f])),'JS unchanged '+f);const m=z=>new Set([...z.matchAll(/[\d,]+円(?:〜|～)?/g)].map(v=>v[0]));for(const x of m(old[f]))must(m(latest[f]).has(x),'price '+f+' '+x);}
must(hrefs(latest['index.html']).includes('/moving/')&&hrefs(latest['index.html']).includes('/aircon/'),'root link discovery');
must(hrefs(latest['house-cleaning/index.html']).includes('/moving/'),'house link reciprocal');
must(hrefs(latest['cursor-test/index.html']).includes('https://teruya1229.github.io/mi-bcs/#pricing'),'MI pricing hash');
must(!latest['cursor-test/index.html'].includes('mi-bcs/#aircon'),'dead anchor removed');
const allFiles=new Set(),html=[];function walk(dir){for(const e of fs.readdirSync(dir,{withFileTypes:true})){if(['.git','node_modules','qa','dist'].includes(e.name))continue;const full=path.join(dir,e.name);if(e.isDirectory())walk(full);else{const p=path.relative(root,path.resolve(full)).split(path.sep).join('/');allFiles.add(p);if(p.endsWith('.html'))html.push(p)}}}walk('.');
const normalize=u=>{let p=decodeURI(u.pathname).replace(/^\/+/,'');if(!p||p.endsWith('/'))p+='index.html';else if(!path.posix.extname(p))p+='/index.html';return p};
const baseFor=f=>'https://teruya1229.github.io/'+(f==='index.html'?'':f.endsWith('/index.html')?f.slice(0,-10):f);
const anchors=s=>{s=s.replace(/<!--[\s\S]*?-->/g,'').replace(/<script\b[^>]*>[\s\S]*?<\/script>/gi,'').replace(/<style\b[^>]*>[\s\S]*?<\/style>/gi,'');return [...s.matchAll(/<a\b[^>]*?\bhref=(["'])([\s\S]*?)\1[^>]*>/gi)].map(m=>m[2].trim())};
const broken=[],frags=[],graph={};for(const f of html){const code=fs.readFileSync(f,'utf8'),links=anchors(code),to=[];for(const href of links){let u;try{u=new URL(href,baseFor(f))}catch{continue}if(u.hostname!=='teruya1229.github.io')continue;const dest=normalize(u);to.push(dest);if(!allFiles.has(dest)){broken.push({source:f,dest,href});continue}if(u.hash&&dest.endsWith('.html')){const fragment=decodeURIComponent(u.hash.slice(1)),text=fs.readFileSync(dest,'utf8');if(!text.includes('id="'+fragment+'"')&&!text.includes("id='"+fragment+"'")&&!text.includes('name="'+fragment+'"')&&!text.includes("name='"+fragment+"'"))frags.push({source:f,dest,hash:fragment});}}graph[f]=[...new Set(to)];}
const core=['index.html','moving/index.html','business-cleaning/index.html','aircon/index.html','house-cleaning/index.html','toilet/index.html','reform/index.html','washlet/index.html','lighting/index.html','mi-bcs/aircon-replacement/index.html','mi-bcs/index.html','prices/index.html','cursor-test/index.html','cursor-test/nanjo.html','cursor-test/naha.html','cursor-test/yaese.html','cursor-test/haebaru.html','cursor-test/yonabaru.html','cursor-test/tomigusuku.html','cursor-test/itoman.html','cursor-test/south.html','cursor-test/central.html','cursor-test/urasoe.html','complete-disassembly/index.html'];
const from=(src,tgt)=>(graph[src]||[]).includes(tgt);must(from('index.html','moving/index.html')&&from('index.html','aircon/index.html'),'root routes');must(from('house-cleaning/index.html','moving/index.html')&&from('moving/index.html','house-cleaning/index.html'),'house moving reciprocity');
must(from('cursor-test/index.html','mi-bcs/index.html'),'MI route');
const regions=['nanjo','naha','yaese','haebaru','yonabaru','tomigusuku','itoman'];for(const x of regions){const p='cursor-test/'+x+'.html';must(from('cursor-test/south.html',p)&&from(p,'cursor-test/south.html'),'south reciprocity '+x)}
must(from('cursor-test/central.html','cursor-test/urasoe.html')&&from('cursor-test/urasoe.html','cursor-test/central.html'),'central/Urasoe');
const reached=new Set(['index.html']),queue=['index.html'];for(let i=0;i<queue.length;i++){for(const p of graph[queue[i]]||[])if(graph[p]&&!reached.has(p)){reached.add(p);queue.push(p)}}must(core.every(x=>reached.has(x)),'core reachable from top '+JSON.stringify(core.filter(x=>!reached.has(x))));
console.log('CROSSLINK_STATIC '+JSON.stringify({html:html.length,anchors:Object.entries(graph).reduce((n,[k,v])=>n+anchors(fs.readFileSync(k,'utf8')).length,0),core:core.length,broken:broken.length,fragments:frags.length,reciprocalSouth:7,reciprocalCentral:true,movingHouse:true,topMovingAndAircon:true,unreachableCore:0}));
must(broken.length===0&&frags.length===0,'unresolved internal links '+JSON.stringify({broken,frags}));
const types={'.html':'text/html; charset=utf-8','.css':'text/css; charset=utf-8','.js':'text/javascript','.jpg':'image/jpeg','.jpeg':'image/jpeg','.png':'image/png','.webp':'image/webp','.svg':'image/svg+xml','.ico':'image/x-icon'};
function serve(v,port){return new Promise((resolve,reject)=>{const svr=http.createServer((req,res)=>{let p=decodeURIComponent(new URL(req.url,'http://127.0.0.1').pathname);let f=path.posix.normalize(p.replace(/^\/+/,''));if(!f||f.endsWith('/'))f+='index.html';if(!path.posix.extname(f))f+='/index.html';if(f==='index.html'&&!p.endsWith('/')&&!p.includes('index'))f='index.html';if(f.includes('..')){res.writeHead(403);return res.end()}if(changed.includes(f)){res.writeHead(200,{'Content-Type':types['.html']});return res.end(v?latest[f]:old[f])};const full=path.resolve(root,f);if(!full.startsWith(root+path.sep)&&full!==root){res.writeHead(403);return res.end()}fs.readFile(full,(err,b)=>{if(err){res.writeHead(404);return res.end()};res.writeHead(200,{'Content-Type':types[path.extname(full)]||'application/octet-stream'});res.end(b)})});svr.listen(port,'127.0.0.1',()=>resolve(svr)).on('error',reject)})}
async function preview(b,v,port,source,width){const ctx=await b.newContext({viewport:{width,height:900},deviceScaleFactor:1,reducedMotion:'reduce'}),p=await ctx.newPage(),errs=[],bad=[];
p.on('pageerror',e=>errs.push(e.message));p.on('response',r=>{if(r.url().startsWith('http://127.0.0.1:'+port+'/')&&r.status()>=400)bad.push(r.status()+' '+r.url())});await p.route('**/*',r=>r.request().url().startsWith('http://127.0.0.1:'+port+'/')?r.continue():r.abort('blockedbyclient'));
const loc=source==='index.html'?'/':('/'+source.replace(/index.html$/,'')),res=await p.goto('http://127.0.0.1:'+port+loc,{waitUntil:'domcontentloaded',timeout:45000});await p.locator('img').evaluateAll(els=>els.forEach(el=>el.loading='eager'));await p.evaluate(async()=>{await Promise.all([...document.images].map(e=>e.decode().catch(()=>{})));for(let y=0;y<document.documentElement.scrollHeight;y+=860){scrollTo(0,y);await new Promise(r=>setTimeout(r,8))}scrollTo(0,0)});
const x=await p.evaluate(()=>({scroll:document.documentElement.scrollWidth,width:innerWidth,images:[...document.images].map(i=>({src:i.getAttribute('src'),ok:i.complete&&i.naturalWidth>0})),faq:document.querySelectorAll('details').length,line:[...document.querySelectorAll('a[href*="lin.ee"]')].map(a=>a.href),tel:[...document.querySelectorAll('a[href^="tel:"]')].map(a=>a.href),moving:[...document.querySelectorAll('a[href="/moving/"]')].length,aircon:[...document.querySelectorAll('a[href="/aircon/"]')].length,pricing:[...document.querySelectorAll('a[href="https://teruya1229.github.io/mi-bcs/#pricing"]')].length,overflows:[...document.querySelectorAll('h1,h2,h3,p,a')].filter(e=>e.getClientRects().length).map(e=>({txt:(e.textContent||'').slice(0,24),r:e.getBoundingClientRect()})).filter(o=>o.r.width>0&&(o.r.left < -8||o.r.right>innerWidth+8)).slice(0,7)}));
if(v||width===320)await p.screenshot({path:path.join(out,source.replace(/\//g,'-')+'-'+(v?'after':'before')+'-'+width+'.png'),fullPage:true,animations:'disabled',timeout:60000});
await ctx.close();return{http:res.status(),...x,errs,bad}}
(async()=>{let s0,s1,b;try{s0=await serve(false,8791);s1=await serve(true,8792);b=await chromium.launch({channel:'chrome',headless:true});const rows=[];for(const source of changed)for(const width of [1440,390,320]){const before=await preview(b,false,8791,source,width),after=await preview(b,true,8792,source,width);
must(before.http===200&&after.http===200,'HTTP '+source+' '+width);
must(after.scroll<=width,'overflow '+source+' '+width+' '+after.scroll);
must(!after.errs.length&&!after.bad.length,'runtime '+source+' '+width+' '+JSON.stringify({errs:after.errs,bad:after.bad}));
must(before.images.length===after.images.length&&after.images.every(i=>i.ok),'assets '+source+' '+width+' '+JSON.stringify(after.images.filter(i=>!i.ok)));
must(before.faq===after.faq&&JSON.stringify(before.line)===JSON.stringify(after.line)&&JSON.stringify(before.tel)===JSON.stringify(after.tel),'protected CTA '+source+' '+width);
if(source==='index.html')must(after.moving>=2&&after.aircon>=1,'root links '+width);
if(source==='house-cleaning/index.html')must(after.moving===1,'house -> moving '+width);
if(source==='cursor-test/index.html')must(after.pricing===1,'MI anchor '+width);
rows.push({page:source,width,http:200,img:after.images.length,faq:after.faq,line:after.line.length,tel:after.tel.length,move:after.moving,aircon:after.aircon,pricing:after.pricing,overflow:0,errors:0,pass:true});}
fs.writeFileSync(path.join(out,'report.json'),JSON.stringify({static:{files:html.length,core:core.length,broken:0,missingFragments:0},rows},null,2));console.log('CROSSLINK_PREVIEW_PASS '+JSON.stringify(rows));
}finally{if(b)await b.close();if(s0)await new Promise(r=>s0.close(r));if(s1)await new Promise(r=>s1.close(r))}})().catch(e=>{console.error('CROSSLINK_PREVIEW_FAIL',e);process.exit(1)});